-- 2026 leg notes: paste into the Supabase SQL editor and run. Updates only the legs whose text changed.
begin;
update legs set beta='A lot of climbs on this one. Rated moderate, but it''s definitely hard. Pay attention to turn signs and dogs. A good early leg to get the body going. 2026 watches read ~720 ft of climb, more than the figure listed.', tags='["Dogs", "Watch the turns"]'::jsonb, team_rating='Hard', surface_text='All pavement' where season_id=(select id from seasons where year=2026) and n=2;
update legs set beta='Hard for sure. Super rocky path for the first half: a long descent that crosses a dry river bed, then it climbs again from there. Very steep climb at mile 4 with some sand barriers to get over, which are a little tricky. In 2026 that climb wasn''t groomed, so it was waist-high weeds the whole way for about half a mile. After that it''s dirt for a little longer, then pavement for the last mile and change.', tags='["No van access", "Rocky"]'::jsonb, team_rating=null, surface_text='75% gravel/trail · 25% pavement' where season_id=(select id from seasons where year=2026) and n=3;
update legs set beta='Starts on paved highway with moderate traffic. Mostly flat. Finishes with a descent on a rocky dirt road. Closer to easy. Not the leg for anyone sensitive to smells: you pass some chicken and cow farms that put off quite a stink. Narrow shoulder on the highway: in a couple of places it felt safer to run in the grass. The gravel downhill at the end is a lot of fun.', tags='["Traffic", "Narrow shoulder"]'::jsonb, team_rating='Easy', surface_text='Pavement / gravel' where season_id=(select id from seasons where year=2026) and n=4;
update legs set beta='Rolling hills with two big inclines. Easy to go fast on the downhill. A lot of good shade. All trail at Hobbs, with plenty of shade. The trail is in fairly good shape, but rocks and small roots hide under leaves and pine needles: you can move, but be cautious. The first 3 miles are mostly downs and straights with a few climbs; the last 2 miles bring more switchbacks and climbs, so save your energy for the end. A fun leg! 2026 watches read ~540 ft of climb, more than the figure listed.', tags='["Shaded", "Rocks + roots under leaves", "Climbs in the last 2 mi"]'::jsonb, team_rating=null, surface_text='100% trail' where season_id=(select id from seasons where year=2026) and n=7;
update legs set beta='Lightly hilly countryside with a few medium-sized hills along the way. Seems moderate. Moderate climbs at the beginning and at the end, all runnable compared with other hills on this course where it''s better to walk. Hardly any shade cover, and you''re likely running it in the heat of the day, so it''s a hot one if temperatures are high. Just a long run, which is why I downgrade it to moderate.', tags='["No shade, hot"]'::jsonb, team_rating='Moderate', surface_text='60% pavement · 40% gravel' where season_id=(select id from seasons where year=2026) and n=9;
update legs set beta='You go up a gnarly hill when you reach gravel — the rock was chunky and challenging for road shoes. Back onto the highway, then gravel again. Both my favorite and least favorite leg. Rated hard, and I definitely agree. In 2026 it could have been done in road shoes, so footwear matters less than it sounds. Mostly gravel roads with a little major highway on a narrow shoulder. Some LONG sustained climbs. Lots of dogs on the route, but they all stayed on their property. 2026 watches read ~1,000 ft of climb, more than the figure listed.', tags='["Chunky rock", "Shoe choice matters", "Long sustained climbs", "Dogs"]'::jsonb, team_rating=null, surface_text='½ mi pavement · 7 mi gravel · 1 mi pavement' where season_id=(select id from seasons where year=2026) and n=10;
update legs set beta='Easy downhill to start. Rolling hills with a couple decent climbs. Gravel was in good shape. Turns onto Hwy 23, which is flat — but be on the lookout for traffic. 2026 watches read ~590 ft of climb, well above the figure listed.', tags='["Traffic on Hwy 23"]'::jsonb, team_rating=null, surface_text='⅓ gravel · ⅔ pavement' where season_id=(select id from seasons where year=2026) and n=11;
update legs set beta='Big decline at the pavement portion. The last half mile is trail and the toughest part — the stairs on the trail are slippery. 2026 watches read ~380 ft of climb, well above the figure listed.', tags='["Slippery stairs"]'::jsonb, team_rating=null, surface_text='Mostly gravel / pavement · last ½ mi gravel' where season_id=(select id from seasons where year=2026) and n=12;
update legs set beta='Cross the street to the dirt road — if you go over the second bridge, you went too far. Pavement leads to a ferry pickup to cross Hwy 412, then finish with a half-mile run after. Once you reach the gravel you are most of the way to the finish; you get back on pavement for the last half mile to full mile. Fairly easy leg, rated moderate mostly because of the distance.', tags='["Navigation", "Hwy 412 ferry crossing"]'::jsonb, team_rating=null, surface_text='⅓ pavement · ⅔ gravel' where season_id=(select id from seasons where year=2026) and n=13;
update legs set beta='Several turns, and some of the signs were removed or hard to see. Pay attention — have the van stick with the runner on this one. Some climbs along the way. Still several turns in 2026: keep an eye out for the course signs so you don''t miss one.', tags='["Navigation!", "Van should shadow runner"]'::jsonb, team_rating=null, surface_text='100% gravel' where season_id=(select id from seasons where year=2026) and n=14;
update legs set beta='Pitch black. Some little rollers with one mild climb. I would rate it moderate. Not sure why this was rated hard: there are some climbs, but overall you''re going downhill. The first 3 miles of gravel were a little chunky with small rocks, so stability was tricky. I was glad when it switched to pavement and I could pick up the pace.', tags='["Pitch black — lights!", "Loose gravel"]'::jsonb, team_rating='Moderate', surface_text='3 mi gravel · 4 mi pavement' where season_id=(select id from seasons where year=2026) and n=15;
update legs set beta='Spooky as hell, but if you can get past that, a quiet and peaceful run. Rated moderate, but I would rate it easy. Dark roads. Starts out paved; mostly flat with some mild climbs. Watch for the fork at the junction of 197 and 6041: turn LEFT onto the gravel on 6041. Garmin didn''t call out that turn (it only alerted once off course) and the glow stick was easy to miss.', tags='["Dark + spooky", "Turn left at 197 / 6041"]'::jsonb, team_rating='Easy', surface_text='40% pavement · 60% gravel' where season_id=(select id from seasons where year=2026) and n=16;
update legs set beta='Leaves the city and heads out onto a paved road. Very dark. Mostly flat with some light-to-medium rolling hills. More moderate. About a third to half a mile in, the street veers left while another road continues straight, and Strava/GPS will tell you to keep straight for 2 miles. Don''t: watch for the signs and glowsticks and veer left. A good climb follows. A runner missed that turn half a mile in during 2026 and went 2 miles off course, so pay attention!', tags='["Very dark", "Veer left early, GPS is wrong"]'::jsonb, team_rating='Moderate', surface_text='100% pavement' where season_id=(select id from seasons where year=2026) and n=19;
update legs set beta='Easy breezy! A few hills. Mostly flat with a few small hills: a good leg to hold a comfortable pace and save some energy.', tags='[]'::jsonb, team_rating=null, surface_text='100% pavement' where season_id=(select id from seasons where year=2026) and n=20;
update legs set beta='Very easy run: smooth road and flat, with a few bridge crossings along the way. Listed as gravel, but in 2026 it was really hard-packed dirt with not much gravel on the road, a nice comfortable jog. There are a few potholes (one of us twisted an ankle in one), but not many, so just bad luck.', tags='["A few bridge crossings"]'::jsonb, team_rating=null, surface_text='Hard-packed dirt road · little gravel' where season_id=(select id from seasons where year=2026) and n=21;
update legs set beta='One steady climb the whole way — very gradual, but steep at times. It just keeps going! Hard to hold the heart rate down. Be ready to climb and go slow on this one. Leans towards hard. Extremely dark and isolated, so it feels spooky. The flat stretches are short, just enough to bring the heart rate down before the climb goes on again.', tags='["Sustained climb", "Dark + isolated"]'::jsonb, team_rating='Hard', surface_text='Gravel / pavement · close to half and half' where season_id=(select id from seasons where year=2026) and n=22;
update legs set beta='About 4 miles of this is rough, loose gravel: the first part sucks, the very end is a piece of cake. The 2025 notes called it broken pavement in very bad shape; either way, pay attention to your footing. A lot of hills and very desolate. You will walk some. It felt good to get to Lake Fort Smith and be done with this one.', tags='["Rough loose gravel", "Desolate"]'::jsonb, team_rating=null, surface_text='~4 mi rough loose gravel · smooth finish' where season_id=(select id from seasons where year=2026) and n=24;
update legs set beta='All uphill for 1.7 miles before a constant downhill to Chester. The downhill felt like it went on forever. Rated hard, and I definitely agree. In 2026, after that opening climb the rest of the leg was very nice and smooth: a good leg overall. It''s long, which is probably why it''s rated hard.', tags='["1.7 mi opening climb", "Endless downhill"]'::jsonb, team_rating=null, surface_text='100% pavement' where season_id=(select id from seasons where year=2026) and n=25;
update legs set beta='Take a left onto the main road out of the parking lot, immediately beginning a substantial climb. Once you reach the summit, bear left to transition to a dirt road for your exchange. The first couple of miles are manageable, steady climbing; the last few miles are rolling hills with some tough climbs. Be prepared to walk some of them and save your energy early. Hard. Long steady climb at the end; many were walking that section.', tags='["Climbs right off the start"]'::jsonb, team_rating='Hard', surface_text='100% pavement' where season_id=(select id from seasons where year=2026) and n=26;
update legs set beta='Easily a hard rating. The hills were a beast and the terrain was difficult. There''s a huge hill between miles 5 and 6, you will likely walk some. Save yourself on the initial hills, because the last one is painful. A bunch of ups and downs: I had to walk one of the climbs in the middle as it got steep. The climb from 5.5 to 6 is super steep. Unless you''re a beast, it''s probably smarter to just walk it, because even walking I was slipping out from under myself. The one good thing about this hard trail: a lot of shade cover along the way if you''re running during the day.', tags='["Beast hills", "Big hill mi 5–6", "Shaded"]'::jsonb, team_rating='Hard', surface_text='100% gravel' where season_id=(select id from seasons where year=2026) and n=27;
update legs set beta='Smooth sailing! Nice paved road, beautiful views. Some substantial uphill, but still moderate overall. Rolling hills with 4 notable climbs. Starts on pavement, then switches to gravel. At midday it was 95% sun with little shade. Moderate feels fair.', tags='["Views"]'::jsonb, team_rating=null, surface_text='Half pavement · half gravel' where season_id=(select id from seasons where year=2026) and n=28;
update legs set beta='Lots of rolling hills with three big climbs — every downhill was met with a climb. Windy road with very little shoulder. Would recommend a flagger. 2026 watches read ~480 ft of climb, well above the figure listed.', tags='["Flagger recommended", "No shoulder"]'::jsonb, team_rating=null, surface_text='100% pavement' where season_id=(select id from seasons where year=2026) and n=29;
commit;
select n, team_rating, left(beta, 60) as beta from legs where season_id=(select id from seasons where year=2026) and n in (2,3,4,7,9,10,11,12,13,14,15,16,19,20,21,22,24,25,26,27,28,29) order by n;  -- expect 22 rows
